//===============================================================
// Namespace
//===============================================================

namespace AppCore.Application.Settings.ServiceSettings;


//===============================================================
// Scheduled Service Repository Interface
//
// Rows are generated by Service Policy : no Create / Delete /
// Restore here, only Configure (price).
//===============================================================

public interface IScheduledServicesRepository
{
    //===========================================================
    // Get All (syncs every policy first)
    //===========================================================

    Task<List<ScheduledServicesDto>> GetAllAsync();


    // One list page (server paging) with Total / Active / Inactive
    Task<AppCore.Application.Common.Paging.PagedResult<ScheduledServicesDto>> GetPagedAsync(
        ServiceSettingsPageRequest request);


    // Public Id -> internal id (live rows only; null = not found)

    Task<long?> GetIdByPublicIdAsync(

        Guid publicId);


    //===========================================================
    // Get By Id (with the sub category / code preview)
    //===========================================================

    Task<ScheduledServicesDto?> GetByIdAsync(
        long id);


    //===========================================================
    // Configure (price; first save assigns code + income ledger)
    //===========================================================

    Task ConfigureAsync(
        ConfigureScheduledServicesDto dto,
        long userId);


    //===========================================================
    // Exists
    //===========================================================

    Task<bool> ExistsAsync(
        long id);
}